Coercing query params with `Number(...)` will produce `NaN` for invalid inputs (e.g. `?limit=abc`), which can propagate into the engine. Consider validating after conversion (e.g. `Number.isFinite`) and either deleting the option, falling back to undefined, or returning a clear client error for invalid numeric parameters.
```suggestion
        const coerceNumericOption = (key: 'top' | 'skip' | 'limit') => {
            if (options[key] != null) {
                const numericValue = Number(options[key]);
                if (Number.isFinite(numericValue)) {
                    options[key] = numericValue;
                } else {
                    delete options[key];
                }
            }
        };
        coerceNumericOption('top');
        coerceNumericOption('skip');
        coerceNumericOption('limit');
```

Stringifying the whole action and doing textual replacement can corrupt JSON when a placeholder appears inside a quoted JSON string but resolves to a non-string (object/array/number), producing invalid JSON (and silently falling back to the original action). A more robust approach is to walk the action object recursively and only perform substitutions on leaf string values, replacing entire-string placeholders with the actual typed value.
```suggestion
    // Walk the action structure and resolve variables only on leaf string values,
    // preserving the actual types of resolved values.
    return this.resolveVariablesInValue(action, context) as QA.TestAction;
  }

  private resolveVariablesInValue(value: unknown, context: Record<string, unknown>): unknown {
    // Handle arrays
    if (Array.isArray(value)) {
      return value.map((item) => this.resolveVariablesInValue(item, context));
    }

    // Handle plain objects
    if (value !== null && typeof value === 'object') {
      const obj: Record<string, unknown> = value as Record<string, unknown>;
      const result: Record<string, unknown> = {};
      for (const [key, v] of Object.entries(obj)) {
        result[key] = this.resolveVariablesInValue(v, context);
      }
      return result;
    }

    // Handle string leaves with placeholder syntax
    if (typeof value === 'string') {
      const str = value;

      // Exact placeholder: "{{ path.to.value }}"
      const exactMatch = str.match(/^\{\{([^}]+)\}\}$/);
      if (exactMatch) {
        const varPath = exactMatch[1].trim();
        const resolved = this.getValueByPath(context, varPath);
        // If undefined, keep the original placeholder string
        return resolved === undefined ? str : resolved;
      }

      // Inline placeholders inside a larger string: "prefix-{{var}}-suffix"
      // Only substitute primitives, and stringify them; leave objects/arrays as-is.
      return str.replace(/\{\{([^}]+)\}\}/g, (match, varPath: string) => {
        const resolved = this.getValueByPath(context, varPath.trim());
        if (resolved === undefined || resolved === null) {
          return match; // Keep unresolved to avoid losing information
        }
        const type = typeof resolved;
        if (type === 'string' || type === 'number' || type === 'boolean') {
          return String(resolved);
        }
        // Non-primitive values are not interpolated into strings to avoid corrupting semantics
        return match;
      });
    }

    // Non-object, non-string leaf values are returned as-is
    return value;
```
